{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Cerivastatin, a statin sharing the same 3,5-dihydroxyhept-6-enoic acid side chain and 4-fluorophenyl-substituted heteroaromatic core as the query, has an absolute oral bioavailability of 60% in humans, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C62"],
      "claim": "Trovafloxacin, a high-transfer fluoroquinolone with a carboxylic acid and fluorophenyl/heteroaromatic features, has 88% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Ketanserin, a high-transfer molecule with fluorophenyl and heterocyclic features, has absolute bioavailability of about 49.3% in young volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Haloperidol, a high-transfer antipsychotic with fluorophenyl and piperidine features, has absolute oral bioavailability of 60–70% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Sacubitril, a high-transfer carboxylic acid-containing drug, has absolute oral bioavailability of at least 60% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Paliperidone, a high-transfer heterocyclic drug, has absolute oral bioavailability of 28% for its extended-release formulation, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "SAHA, a high-transfer aromatic hydroxamic acid, has absolute oral bioavailability of 43% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Paltusotine, a high-transfer oral drug with fluorinated aromatic and heteroaromatic features, has absolute bioavailability of 69% in healthy participants, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "SB-681323, a high-transfer fluorinated heteroaromatic p38 inhibitor, has systemic availability of approximately 50%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C66"],
      "claim": "Propranolol shows low absolute bioavailability (15.8%) in normal volunteers due to extensive first-pass metabolism; this is contradictory evidence but arises from a different chemical class and is outweighed by statin-specific and multiple high-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high: the query is a statin with the same dihydroxyheptenoic acid pharmacophore as cerivastatin, whose human absolute oral bioavailability is ~60%. Multiple high-transfer analogues (trovafloxacin, ketanserin, haloperidol, sacubitril, paliperidone, SAHA, paltusotine, SB-681323) all show F ≥20%, mostly 28–88%. The only low-F evidence, propranolol, reflects extensive first-pass metabolism in a different chemical class and is outweighed.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is included; prediction relies on high-transfer analogues, especially cerivastatin.",
    "Propranolol low-F records introduce dose-dependent first-pass metabolism uncertainty, but the query's statin scaffold and multiple high-F analogues mitigate this concern."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

